mapper.insert:
insert into ETR_SEC_POSITION (PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, HODING_TYPE, CDATE, AMOUNT, CCY, FACE_VALUE, P_FINPROD_ID, INV_AIM, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) VALUES targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.HODING_TYPE, #{batchDate,jdbcType=DATE}, SUM(targetTable.AMOUNT), targetTable.CCY, null, null, targetTable.INV_AIM, 'system', null, NOW(), 'system', NOW() FROM ( SELECT PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, AMOUNT, CCY, IFNULL(INV_AIM, '999999') as INV_AIM, HODING_TYPE FROM ETR_SEC_POSITION WHERE HODING_TYPE = #{POSITION_TYPE_E01,jdbcType=VARCHAR} and CDATE = #{lastDate,jdbcType=DATE}
and (
)
union all SELECT PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999') as SEC_ACCT_ID, FINPROD_ID, BRANCH, sum(AMOUNT) as AMOUNT, CCY, IFNULL(INV_AIM, '999999') as INV_AIM, HODING_TYPE FROM ETR_SEC_POSITION_FLOW WHERE HODING_TYPE = #{POSITION_TYPE_E01,jdbcType=VARCHAR} and CDATE = #{batchDate,jdbcType=DATE}
and (
)
GROUP BY PORTFOLIO_ID, IFNULL(SEC_ACCT_ID, '999999'), FINPROD_ID, BRANCH, CCY, IFNULL(INV_AIM, '999999'), HODING_TYPE ) targetTable group by targetTable.PORTFOLIO_ID, targetTable.SEC_ACCT_ID, targetTable.FINPROD_ID, targetTable.BRANCH, targetTable.HODING_TYPE, targetTable.CCY, targetTable.INV_AIM
